-- Topic: Written Representations
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Evaluating response when contradictory evidence undermines a specific representation
(1, 'Written Representations', 'Ashford & Palmer CPA is auditing Northbridge Enterprises for the year ended December 31, 2025. Management''s signed representation letter states that all transactions have been recorded in the accounting records. However, the audit team discovers $1.2 million in unrecorded vendor invoices from November 2025. When confronted, management attributes the omission to a processing backlog. The engagement partner''s most appropriate course of action is to:', '["Issue a qualified opinion for the scope limitation created by the recording failure", "Request management to correct the financial statements and provide an updated representation letter without further investigation", "Reconsider the reliability of all management representations and evaluate the effect on other audit evidence obtained during the engagement", "Withdraw from the engagement immediately and report the contradiction to regulators"]'::jsonb, 2, 'Under AU-C 580.A23, when a written representation is contradicted by other audit evidence, the auditor must investigate the circumstances and reconsider the reliability of other representations made by management. This may require reevaluating other audit evidence that depended on management''s assertions. Simply requesting a correction (choice B) is insufficient because the contradiction raises broader concerns about the reliability of management''s representations that extend beyond the single omission.', 'hard', 4),

-- Q2: easy / L1 — Representation letter references the applicable financial reporting framework
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should reference:', '["The applicable financial reporting framework used to prepare the financial statements", "The auditor''s internal quality control policies and procedures", "The entity''s industry benchmarks for financial performance", "The prior year''s audit adjustments and reclassification entries"]'::jsonb, 0, 'Under AU-C 580.10, the management representation letter should reference the applicable financial reporting framework (e.g., U.S. GAAP) used in the preparation and fair presentation of the financial statements. This establishes the basis for management''s assertions about the financial statements. The auditor''s quality control policies (choice B) are addressed in the engagement letter and firm procedures, not in the management representation letter.', 'easy', 1),

-- Q3: medium / L3 — Analyzing how an undisclosed accounting policy change contradicts the policy representation
(1, 'Written Representations', 'During the audit of Redstone Manufacturing for the year ended December 31, 2025, Garrett & Webb CPA obtains a representation letter in which management states that it has selected and applied accounting policies it considers appropriate. However, the audit team discovers that Redstone changed its revenue recognition method mid-year without disclosure. The most likely effect of this finding on the auditor''s assessment is that:', '["No effect, because the representation addresses only appropriateness, not disclosure", "The auditor should accept the representation and note the change as an emphasis-of-matter paragraph", "The undisclosed change is a legal matter outside the scope of the representation letter", "The auditor should investigate the inconsistency between the representation and the evidence and consider modifying the opinion if unresolved"]'::jsonb, 3, 'Under AU-C 580.A22, when audit evidence contradicts a management representation, the auditor must resolve the inconsistency and reconsider the reliability of the representations. An undisclosed mid-year accounting policy change may contradict management''s assertion that policies were appropriately applied and disclosed. Noting it as emphasis-of-matter (choice B) is inappropriate because an undisclosed policy change may constitute a GAAP departure requiring opinion modification, not merely emphasis.', 'medium', 3),

-- Q4: easy / L1 — Period covered by written representations
(1, 'Written Representations', 'Under AU-C 580, the management representation letter covers:', '["Only the current fiscal year under audit", "All periods referred to in the auditor''s report", "The current year plus one subsequent quarter", "All periods since the entity''s date of incorporation"]'::jsonb, 1, 'Under AU-C 580.15, written representations cover all periods referred to in the auditor''s report. When comparative financial statements are presented, the representations extend to all periods covered by the auditor''s opinion. Limiting representations to only the current year (choice A) would be insufficient when the auditor''s report references prior period financial statements that also require management''s assertions.', 'easy', 1),

-- Q5: easy / L1 — Form of the representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter is typically prepared:', '["Exclusively by the auditor on the audit firm''s letterhead", "By the entity''s external legal counsel on legal stationery", "On the entity''s letterhead or in a form provided by the auditor and signed by management", "As an oral statement transcribed and notarized by the audit team"]'::jsonb, 2, 'Under AU-C 580.A16, the representation letter is typically prepared on the entity''s letterhead or, alternatively, the auditor may provide a draft for management to review, sign, and submit. The key requirement is that management acknowledges the representations by signing the letter. An auditor-prepared letter on firm letterhead (choice A) is incorrect because the letter must originate from or be adopted by management, not appear to come from the auditor.', 'easy', 1),

-- Q6: medium / L2 — Applying the uncorrected misstatements attachment requirement
(1, 'Written Representations', 'Palmer & Reid CPA completes the audit of Sunbelt Distribution for the year ended December 31, 2025. The audit team identified $38,000 in aggregate uncorrected misstatements that management considers immaterial. When preparing the representation letter, the engagement partner should ensure it includes:', '["A summary of the uncorrected misstatements and management''s representation that they are immaterial individually and in the aggregate", "Only a general statement that management is aware of uncorrected misstatements without specifying any amounts", "No reference to uncorrected misstatements if they fall below performance materiality", "A requirement that management correct all identified misstatements before signing the letter"]'::jsonb, 0, 'Under AU-C 580.12, the representation letter must include or attach a summary of uncorrected misstatements identified during the audit, along with management''s representation that the effects are immaterial, individually and in the aggregate, to the financial statements as a whole. A vague acknowledgment without amounts (choice B) does not satisfy the standard because management must explicitly acknowledge the specific misstatements it has chosen not to correct.', 'medium', 2),

-- Q7: medium / L2 — Applying the subsequent events representation within the letter
(1, 'Written Representations', 'Caldwell & Hughes CPA is finalizing the audit of Meridian Healthcare for the year ended December 31, 2025. The auditor''s report will be dated March 3, 2026. The engagement partner ensures the representation letter includes a statement about events between December 31, 2025 and March 3, 2026. This representation should state that management has:', '["Performed its own subsequent events review and found no reportable items", "Certified that no events of any kind occurred during the subsequent period", "Agreed to indemnify the auditor for any undisclosed subsequent events", "Disclosed to the auditor all events occurring through the report date that require adjustment or disclosure"]'::jsonb, 3, 'Under AU-C 580.11, the representation letter should include management''s representation that it has disclosed all events occurring between the balance sheet date and the date of the auditor''s report that require adjustment or disclosure under the applicable framework. Certifying that no events occurred (choice B) is unrealistic and not what the standard requires—the representation addresses disclosure of relevant events, not the absence of all activity during the subsequent period.', 'medium', 2),

-- Q8: hard / L4 — Evaluating response when new management lacks prior period knowledge
(1, 'Written Representations', 'Waverly & Dunn CPA is auditing Brighton Capital Corp. for the years ended December 31, 2025 and 2024 (comparative statements). Brighton''s CEO and CFO both joined in June 2025, replacing the prior management team. The new executives state they cannot make representations about periods before their tenure because they have no personal knowledge of those transactions. The engagement partner should:', '["Accept representations only for the 2025 period and disclaim on the 2024 comparatives", "Request that the new management make all required representations after performing sufficient inquiry and review of prior period records to support them", "Issue a qualified opinion for both periods citing the management transition as a scope limitation", "Require the former CEO and CFO to sign a separate representation letter covering the 2024 fiscal year"]'::jsonb, 1, 'Under AU-C 580.A11, when current management was not present during all periods covered by the report, the auditor still obtains representations from current management for all such periods. Management is expected to take reasonable steps—such as reviewing records, minutes, and prior audit files—to inform itself sufficiently to provide the representations. Disclaiming on comparatives (choice A) is unnecessary because the standard requires current management to obtain sufficient knowledge, not personal involvement in prior period transactions.', 'hard', 4),

-- Q9: medium / L3 — Analyzing the distinction between requested and required representations
(1, 'Written Representations', 'During the audit of Ironclad Security Solutions for the year ended December 31, 2025, Mercer & Shaw CPA requests that management include in the representation letter a statement about the entity''s cybersecurity incident response procedures. Management''s counsel objects, arguing this representation is not mandated by AU-C 580. The most accurate analysis of this situation is that:', '["The auditor cannot request any representations beyond those explicitly listed in AU-C 580", "Management''s counsel is correct and the auditor must remove the request entirely", "AU-C 580 permits the auditor to request additional representations beyond the specifically required ones when the auditor considers them necessary to support other audit evidence", "The requested representation automatically becomes a required representation once included in the letter"]'::jsonb, 2, 'Under AU-C 580.13, the auditor may request additional written representations beyond those specifically required by the standard when the auditor determines they are necessary to support other audit evidence. These requested representations supplement the required ones. Choice A is incorrect because AU-C 580 explicitly contemplates that auditors will request representations tailored to the entity''s specific circumstances and risk profile beyond the minimum required list.', 'medium', 3),

-- Q10: easy / L1 — Representation about management's responsibility for fair presentation
(1, 'Written Representations', 'Which of the following is a required representation about management''s responsibilities under AU-C 580?', '["Management is responsible for selecting the audit firm and setting the audit scope", "Management acknowledges that the engagement fee is reasonable for the services rendered", "Management certifies that all internal controls operated effectively throughout the year", "Management acknowledges its responsibility for the preparation and fair presentation of the financial statements"]'::jsonb, 3, 'Under AU-C 580.10, management must provide a written representation acknowledging its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. This foundational representation establishes management''s ownership of the financial statements. Choice C is incorrect because management represents responsibility for designing and maintaining internal control, not that controls operated effectively throughout the period.', 'easy', 1),

-- Q11: medium / L2 — Applying the accounting policies representation to a specific policy change
(1, 'Written Representations', 'Hartwell & Barnes CPA is auditing Pinnacle Supply Co. for the year ended December 31, 2025. Management changed its inventory costing method from FIFO to weighted average during the year. The representation letter should include management''s acknowledgment that:', '["The selection and application of accounting policies, including the change in inventory costing method, are appropriate under the applicable financial reporting framework", "The auditor approved the accounting policy change before implementation", "All accounting policy changes are automatically considered appropriate if consistently applied going forward", "The predecessor inventory method was inappropriate and the new method corrects a prior period error"]'::jsonb, 0, 'Under AU-C 580.11, management must represent that the significant accounting policies selected and applied are appropriate under the applicable financial reporting framework. When an accounting policy change occurs, this representation encompasses management''s acknowledgment that the change is appropriate under the framework. Choice B is incorrect because the auditor evaluates but does not approve accounting policy changes—the responsibility for selecting appropriate policies rests solely with management.', 'medium', 2),

-- Q12: medium / L2 — Applying the going concern representation
(1, 'Written Representations', 'Fletcher & Associates CPA is auditing Bayshore Hospitality Group for the year ended December 31, 2025. Bayshore has experienced declining revenues for three consecutive years and recently violated a bank debt covenant. The representation letter should include management''s statement that:', '["The auditor has sole responsibility for evaluating the entity''s ability to continue as a going concern", "Management has disclosed to the auditor its knowledge of events or conditions and its plans that may affect the entity''s ability to continue as a going concern", "Going concern evaluation is not required because Bayshore has not yet filed for bankruptcy protection", "The debt covenant violation has been automatically waived by the lender and requires no disclosure"]'::jsonb, 1, 'Under AU-C 580.11, management should represent that it has disclosed all information relevant to the going concern assessment, including its knowledge of events or conditions and its plans that may affect the entity''s ability to continue as a going concern. This representation is critical when going concern indicators exist. Choice A is incorrect because management shares responsibility for the going concern assessment—the auditor evaluates management''s own assessment rather than making the determination independently.', 'medium', 2),

-- Q13: easy / L1 — Representation letter is addressed to the auditor
(1, 'Written Representations', 'Under AU-C 580, the management representation letter is addressed to:', '["The entity''s board of directors or audit committee chair", "The Securities and Exchange Commission or relevant regulator", "The auditor who is performing the audit engagement", "The entity''s shareholders at the annual general meeting"]'::jsonb, 2, 'Under AU-C 580.A15, the management representation letter is addressed to the auditor because it serves as audit evidence provided directly from management to the auditor. The letter confirms management''s acknowledgment of its responsibilities and other matters relevant to the engagement. Addressing it to the board (choice A) would be inappropriate because the representations are made to the auditor as part of the audit evidence framework, not as a governance communication.', 'easy', 1),

-- Q14: easy / L2 — Determining who constitutes appropriate management for signing
(1, 'Written Representations', 'Grayson & Cole CPA is auditing Summit Retail Holdings for the year ended December 31, 2025. The company has a CEO, CFO, controller, and VP of Operations. Under AU-C 580, the representation letter should be signed by members of management who are:', '["The most senior individuals in the corporate hierarchy regardless of their financial knowledge", "Officers who hold active CPA licenses or equivalent professional certifications", "Available on the date the auditor''s report is scheduled to be issued", "Responsible for and knowledgeable about the matters covered in the representations"]'::jsonb, 3, 'Under AU-C 580.19, the representation letter should be signed by members of management whom the auditor believes are responsible for and knowledgeable about, directly or through others, the matters covered in the representations. Typically this means the CEO and CFO or their equivalents. Choice A is incorrect because seniority alone is insufficient—the signatories must have relevant knowledge of the financial and operational matters addressed in the representations.', 'easy', 2),

-- Q15: medium / L3 — Analyzing representation about title to assets and rights/obligations assertion
(1, 'Written Representations', 'During the audit of Crestview Real Estate Partners for the year ended December 31, 2025, Donovan & Hughes CPA obtains a representation letter in which management asserts that the entity has satisfactory title to all owned assets. The audit team then discovers that a commercial property valued at $4.8 million is subject to an undisclosed lien. The most likely implication of this finding is that:', '["The representation about title directly supports the rights and obligations assertion, and the undisclosed lien may indicate a financial statement misstatement requiring investigation", "The lien is a legal matter outside the scope of the audit that does not affect the representation letter", "The title representation applies only to personal property and not to real estate holdings", "The auditor should update the representation letter to exclude the liened property from the title assertion"]'::jsonb, 0, 'Under AU-C 580 and the assertion framework in AU-C 315, the representation about satisfactory title to assets directly supports the rights and obligations assertion. An undisclosed lien on a $4.8 million property contradicts this representation and may indicate a material misstatement requiring further investigation and potential opinion modification. Choice B is incorrect because liens directly affect the entity''s rights to assets and fall squarely within the scope of the audit.', 'medium', 3),

-- Q16: easy / L1 — Representation about access to all records and personnel
(1, 'Written Representations', 'A required written representation under AU-C 580 states that management has provided the auditor with:', '["A certification that the financial statements are entirely free from all errors", "Access to all information that management believes is relevant to the audit, including records, documentation, and other matters", "Written approval from the entity''s external legal counsel for every significant transaction", "A comprehensive list of all competitors and their market share for benchmarking purposes"]'::jsonb, 1, 'Under AU-C 580.11(b), management must represent that it has provided the auditor with access to all information that management believes is relevant to the preparation and fair presentation of the financial statements, including records, documentation, and other matters. Choice A is incorrect because management represents responsibility for fair presentation of the financial statements, not that the statements are entirely error-free—no such certification is contemplated by the standard.', 'easy', 1),

-- Q17: easy / L1 — Why written form is required rather than oral
(1, 'Written Representations', 'Under AU-C 580, management representations must be in written form primarily because:', '["Written form documents management''s acknowledgment of its responsibilities and reduces the possibility of misunderstandings", "Oral representations are completely prohibited under all professional auditing standards", "Written representations carry greater legal weight than all other forms of audit evidence combined", "The SEC mandates written representations for all audits of both public and private companies"]'::jsonb, 0, 'Under AU-C 580.A2, written representations are required because they document management''s acknowledgment of its responsibilities and reduce the possibility of misunderstandings between the auditor and management. Written form provides a more reliable record than oral communication. Choice B is incorrect because oral representations (inquiries) are not prohibited—they are a standard audit procedure—but AU-C 580 requires certain key representations be documented in writing for clarity.', 'easy', 1),

-- Q18: medium / L2 — Applying the compliance with laws and regulations representation
(1, 'Written Representations', 'Thornton & Associates CPA is auditing Apex Pharmaceuticals for the year ended December 31, 2025. The engagement team discovers that Apex received a warning letter from the FDA regarding manufacturing compliance in October 2025. The representation letter should include management''s acknowledgment that:', '["The entity is exempt from regulatory compliance representations due to its specialized industry", "Management certifies that the entity has never violated any federal or state law or regulation", "Management has disclosed to the auditor all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements", "The FDA warning letter is a privileged legal communication excluded from representation letter requirements"]'::jsonb, 2, 'Under AU-C 580.11, management must represent that it has disclosed all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements. The FDA warning letter is directly relevant to this representation. Choice B is incorrect because the standard requires disclosure of known or suspected noncompliance, not a certification of perfect compliance with all laws and regulations.', 'medium', 2),

-- Q19: medium / L2 — Representation about completeness of related party identification
(1, 'Written Representations', 'Canton & Price CPA is auditing Lakeview Holdings for the year ended December 31, 2025. During testing, the audit team identifies that Lakeview''s CEO owns a 45% interest in a vendor that was not disclosed as a related party. The representation letter should specifically include management''s statement that:', '["All vendors with ownership interests exceeding 50% have been identified as related parties", "Management has disclosed the identity of all related parties and all related-party relationships and transactions of which it is aware", "Related-party identification is solely the auditor''s responsibility and is not a subject of management representations", "Only related parties involved in transactions exceeding $100,000 must be included in the representation letter"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that it has disclosed the identity of all the entity''s related parties and all related-party relationships and transactions of which it is aware. This representation covers both the identity of related parties and the completeness of disclosed transactions with those parties. Choice A is incorrect because related-party thresholds are based on significant influence or control criteria under the applicable framework, not a fixed 50% ownership test.', 'medium', 2),

-- Q20: hard / L4 — Evaluating response when representation letter is received after the report date
(1, 'Written Representations', 'Morrison & Kline CPA issues the auditor''s report for Westfield Technologies on March 12, 2026, for the year ended December 31, 2025. Due to management travel schedules, the signed representation letter is not received until March 18, 2026. The engagement partner must evaluate the most appropriate response to this situation. The auditor should:', '["Accept the letter because it was received within a reasonable time after the report date", "Request that management backdate the representation letter to March 12, 2026 to match the report date", "Issue a revised auditor''s report with the new date of March 18, 2026", "Determine that the auditor''s report should not have been released because the signed representation letter is a prerequisite for issuing the report"]'::jsonb, 3, 'Under AU-C 580.15, the written representation letter must be dated as of the date of the auditor''s report, and the auditor should obtain the signed letter before or on that date as a prerequisite for issuing the report. Releasing the report before obtaining the required representation letter represents a departure from AU-C 580 requirements. Backdating the letter (choice B) would be inappropriate because it would misrepresent when management actually signed and acknowledged the representations.', 'hard', 4),

-- Q21: medium / L3 — Analyzing how a side-agreement omission affects reliability of representations
(1, 'Written Representations', 'During the audit of Crossroad Logistics for the year ended December 31, 2025, Beckett & Hayes CPA discovers a side agreement between Crossroad and a major customer that modifies payment terms on $2.1 million in receivables. The side agreement was not disclosed to the auditor during fieldwork. The most likely effect of this discovery on the auditor''s assessment is that:', '["The omission calls into question the completeness representation and may indicate that other undisclosed arrangements exist", "The side agreement affects only the accounts receivable confirmation process and has no impact on the representation letter", "The auditor should add a representation about side agreements but take no further investigative action", "Side agreements are outside the scope of AU-C 580 and are addressed exclusively by AU-C 550"]'::jsonb, 0, 'Under AU-C 580.11(b), management represents that it has provided the auditor with all relevant information. An undisclosed side agreement modifying $2.1 million in receivable terms directly contradicts the completeness representation. The auditor should reconsider the reliability of other representations and evaluate whether additional undisclosed arrangements may exist. Choice B is incorrect because the omission affects the fundamental completeness of information provided to the auditor, extending well beyond just the confirmation process.', 'medium', 3),

-- Q22: hard / L4 — Evaluating course of action when CEO refuses to sign but CFO signs
(1, 'Written Representations', 'During the audit of Prism Analytics Corp. for the year ended December 31, 2025, Warren & Associates CPA prepares the management representation letter. The CFO signs without objection, but the CEO refuses to sign, stating that the CFO''s signature alone should be sufficient since the CFO oversees all financial matters. The engagement partner must evaluate the most appropriate response.', '["Accept the CFO''s signature alone since the CFO is the highest financial authority in the organization", "Issue a qualified opinion noting that the CEO declined to sign the management representation letter", "Evaluate whether the CEO''s refusal constitutes a failure to provide required representations and consider the effect on the auditor''s report, including the possibility of disclaiming an opinion", "Request the audit committee chair to sign the representation letter in place of the CEO"]'::jsonb, 2, 'Under AU-C 580.19–.20, the auditor obtains representations from those responsible for and knowledgeable about the matters covered. The CEO typically has unique knowledge of operational and strategic matters. The CEO''s refusal may constitute a failure to provide required representations, which could lead to a disclaimer under AU-C 580.20. Accepting only the CFO''s signature (choice A) may be insufficient if the CEO possesses knowledge of operational matters outside the CFO''s direct purview that are relevant to the financial statements.', 'hard', 4),

-- Q23: medium / L3 — Analyzing the representation about estimates and assumptions
(1, 'Written Representations', 'Martin & Shaw CPA is auditing Oakridge Manufacturing for the year ended December 31, 2025. The financial statements include a $6.3 million goodwill impairment estimate based on discounted cash flow projections. Management''s representation letter states that the assumptions used in accounting estimates are reasonable. The most accurate analysis of this representation is that:', '["The representation eliminates the auditor''s need to independently evaluate the reasonableness of the assumptions", "The representation supports but does not replace the auditor''s responsibility to evaluate whether the methods, data, and assumptions underlying the estimate are appropriate", "The representation is not required because accounting estimates are inherently uncertain and cannot be represented as reasonable", "The representation shifts the liability for any estimation error from management to the auditor"]'::jsonb, 1, 'Under AU-C 580.11 and AU-C 540, management represents that the significant assumptions used in making accounting estimates are reasonable. However, this representation supplements rather than replaces the auditor''s independent evaluation of the estimate''s methods, data, and assumptions. Choice A is incorrect because AU-C 540 requires the auditor to independently assess the reasonableness of assumptions regardless of management''s representation, since representations alone are not sufficient appropriate audit evidence.', 'medium', 3),

-- Q24: easy / L1 — Representation about management's responsibility for internal control
(1, 'Written Representations', 'Under AU-C 580, management must provide a written representation acknowledging responsibility for:', '["Performing all substantive audit procedures on behalf of the external auditor", "Selecting the audit engagement partner and determining the audit scope", "Setting the materiality threshold used throughout the audit engagement", "The design, implementation, and maintenance of internal control relevant to the preparation of the financial statements"]'::jsonb, 3, 'Under AU-C 580.10(b), management must represent that it is responsible for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements free from material misstatement. This confirms management''s ownership of the control environment. Choice C is incorrect because determining materiality is an auditor responsibility under AU-C 320, not a management function that would appear in the representation letter.', 'easy', 1),

-- Q25: hard / L4 — Evaluating response when litigation representation contradicts attorney's letter
(1, 'Written Representations', 'During the audit of Silverton Industries for the year ended December 31, 2025, Burke & Connelly CPA receives a management representation letter stating that all known litigation and claims have been disclosed. However, the attorney''s response letter identifies a pending $3.5 million breach-of-contract lawsuit that management did not include in the financial statement disclosures or mention to the auditors. The engagement partner should:', '["Discuss the inconsistency with management, request an explanation, and reconsider the reliability of management''s representations regarding the completeness of disclosures", "Accept management''s representation because it was signed by both the CEO and CFO and therefore takes precedence", "Rely exclusively on the attorney''s letter and modify the audit opinion without any further management inquiry", "Conclude that the attorney violated client confidentiality and disregard the attorney''s response letter"]'::jsonb, 0, 'Under AU-C 580.A22, when information from another source contradicts a management representation, the auditor must investigate the inconsistency and reconsider the reliability of management''s representations. The undisclosed $3.5 million lawsuit directly contradicts the completeness representation about litigation. Choice B is incorrect because the signatures of the CEO and CFO do not override contradictory evidence from the attorney—audit evidence must be evaluated for consistency regardless of the signatories.', 'hard', 4),

-- Q26: medium / L2 — Applying the plans and intentions representation to HTM securities
(1, 'Written Representations', 'Langford & Associates CPA is auditing Beacon Manufacturing for the year ended December 31, 2025. Beacon holds $8.2 million in held-to-maturity debt securities. During fieldwork, management mentions it may need to sell some of these securities to meet cash flow needs in 2026. The representation letter should address:', '["A certification that all held-to-maturity securities will be retained until their scheduled maturity dates", "A certification that the securities have been independently appraised at current fair market value", "Management''s plans and intentions that may affect the carrying value or classification of assets, including its intent and ability to hold the securities to maturity", "An assertion that projected cash flows for 2026 have been verified by an independent financial advisor"]'::jsonb, 2, 'Under AU-C 580.11, management should represent its plans and intentions that may affect the carrying value or classification of assets and liabilities. For held-to-maturity securities, management''s intent and ability to hold investments to maturity is critical to their classification under the applicable framework. Choice A is incorrect because a blanket certification of intent is not an appropriate representation—the standard requires disclosure of management''s actual plans and intentions, which the auditor then evaluates for reasonableness.', 'medium', 2),

-- Q27: medium / L3 — Analyzing the completeness of minutes-of-meetings representation
(1, 'Written Representations', 'During the audit of Clearfield Technologies for the year ended December 31, 2025, Porter & Lang CPA requests management confirm that all minutes of meetings have been made available. Management provides board meeting minutes but states that an executive committee meeting in September 2025 was informal and no minutes were recorded. The most appropriate analysis of this situation is that:', '["The absence of minutes is immaterial because informal meetings do not require documentation for audit purposes", "The auditor should evaluate whether significant decisions were made at the meeting that could affect the financial statements and consider whether the completeness representation is compromised", "Executive committee minutes are outside the scope of the auditor''s inquiry under AU-C 580", "The auditor should accept the representation as written since all formal board meeting minutes were provided"]'::jsonb, 1, 'Under AU-C 580.11(b), management represents completeness of information provided, which encompasses minutes from all governance meetings where financial decisions may occur. The auditor should inquire about the nature of discussions at the undocumented meeting to assess whether the absence of minutes affects audit evidence completeness. Choice A is incorrect because the formality of a meeting does not determine its audit relevance—significant decisions affecting the financial statements can occur in informal committee sessions.', 'medium', 3),

-- Q28: hard / L3 — Analyzing initial audit representation letter considerations for prior periods
(1, 'Written Representations', 'Haines & Cooper CPA has been engaged for the initial audit of Ridgecrest Industries for the year ended December 31, 2025. The predecessor auditor issued an unmodified opinion on the 2024 financial statements. Ridgecrest presents comparative statements for both years. In this initial engagement, the representation letter should:', '["Cover only the 2025 period because the predecessor auditor already obtained representations for 2024", "Exclude prior period representations unless the predecessor auditor''s opinion was modified or qualified", "Reference the predecessor auditor''s representation letter as incorporated by reference into the current letter", "Cover all periods referred to in the current auditor''s report, including the 2024 comparative period"]'::jsonb, 3, 'Under AU-C 580.15, written representations cover all periods referred to in the auditor''s report. Even in an initial audit where a predecessor auditor previously reported, the current auditor must obtain representations from current management for all periods referenced in its report. Choice A is incorrect because the predecessor auditor''s representations were made to that auditor—they do not transfer to the successor, and current management must provide its own representations covering the comparative period.', 'hard', 3),

-- Q29: medium / L3 — Analyzing when the completeness of liabilities representation is insufficient alone
(1, 'Written Representations', 'During the audit of Stonebridge Contractors for the year ended December 31, 2025, Walsh & Henderson CPA obtains a representation letter in which management states that all liabilities have been recorded. The audit team notes that Stonebridge has a history of unrecorded warranty obligations identified in prior year audits. The most appropriate analysis of the sufficiency of this representation is that:', '["The representation alone is insufficient given the entity''s history, and the auditor should perform additional substantive procedures to test the completeness of warranty liabilities", "The representation fully satisfies the requirement for evidence about completeness of liabilities regardless of prior audit history", "The auditor should request a separate warranty-specific representation letter from the operations manager", "The representation is unnecessary because completeness of liabilities is tested exclusively through search-for-unrecorded-liabilities procedures"]'::jsonb, 0, 'Under AU-C 580.04, written representations are necessary audit evidence but do not substitute for other audit procedures. Given Stonebridge''s history of unrecorded warranty obligations, the completeness representation, while required, does not provide sufficient evidence standing alone. The auditor should design additional substantive procedures targeting warranty liabilities. Choice B is incorrect because representations never independently satisfy the evidence requirement—they complement other procedures, especially when historical patterns indicate elevated risk.', 'medium', 3),

-- Q30: medium / L2 — Applying the representation about unasserted claims and assessments
(1, 'Written Representations', 'Kessler & Martin CPA is auditing Riverdale Construction for the year ended December 31, 2025. Riverdale''s legal counsel has identified a potential environmental contamination issue at a recently acquired property, but no claim has been formally asserted. The representation letter should include management''s acknowledgment regarding:', '["Only claims that have been formally filed in court as of the balance sheet date", "Unasserted claims and assessments that legal counsel has advised are probable of being asserted and that must be disclosed under the applicable financial reporting framework", "All environmental matters regardless of whether they have any financial statement implications", "Claims that are expected to be filed within exactly 30 days of the auditor''s report date"]'::jsonb, 1, 'Under AU-C 580.11 and AU-C 501, management should represent that it has disclosed unasserted claims or assessments that the entity''s legal counsel has advised are probable of being asserted and that must be disclosed under the applicable financial reporting framework. The potential environmental contamination requires evaluation even though unasserted. Choice A is incorrect because limiting disclosure to formally filed claims would exclude material contingencies that management is aware of but that have not yet been asserted against the entity.', 'medium', 2)
;

COMMIT;
